export const JOURNAL_PHASES: string[] = ["Kış planı", "Bakım ve hazırlık", "Çiçek ve bekleyiş", "Meyve tutumu", "Büyüme ve denge", "Hasada hazırlık", "Hasat ve ilk sergi", "Sergi, patik ve eleme", "Kutu ve arşiv", "Sofra ve anlatı", "Dinlenme ve onarım", "Defter kapanışı"];
export const JOURNAL_FOCUS_AREAS: string[] = ["Bahçe", "Atölye", "Kayıt", "Mutfak"];

export function journalEntryForDate(monthIndex: number, dayOfMonth: number): DailyJournalEntry | undefined {
  return DAILY_JOURNAL.find((entry) => entry.monthIndex === monthIndex && entry.dayOfMonth === dayOfMonth);
}
